    "push.section": { en: "Reminders", ar: "التنبيهات", es: "Recordatorios", fr: "Rappels", de: "Erinnerungen", ja: "リマインダー", zh: "提醒" },
    "push.on": { en: "On for this device. Each habit is reminded at its own time.", ar: "مفعّلة على هذا الجهاز. تُذكَّر بكل عادة في وقتها الذي حدّدته.", es: "Activados en este dispositivo. Cada hábito a su hora.", fr: "Activés sur cet appareil. Chaque habitude à son heure.", de: "Auf diesem Gerät aktiv. Jede Gewohnheit zu ihrer Zeit.", ja: "この端末で有効です。習慣ごとに設定した時刻に通知します。", zh: "已在此设备开启。每个习惯按自己的时间提醒。" },
    "push.off": { en: "Off. Turning them on asks the browser for permission.", ar: "متوقفة. سيطلب التفعيل إذنًا من المتصفح.", es: "Desactivados. Al activarlos, el navegador pedirá permiso.", fr: "Désactivés. Les activer demandera l'autorisation au navigateur.", de: "Aus. Beim Aktivieren fragt der Browser um Erlaubnis.", ja: "オフです。オンにするとブラウザが許可を求めます。", zh: "已关闭。开启时浏览器会请求权限。" },
    "push.blocked": { en: "Blocked in this browser. Only its own settings can allow them again.", ar: "محظورة في هذا المتصفح. وحدها إعدادات المتصفح نفسه يمكنها السماح بها من جديد.", es: "Bloqueados en este navegador. Solo sus ajustes pueden permitirlos de nuevo.", fr: "Bloqués dans ce navigateur. Seuls ses réglages peuvent les réautoriser.", de: "In diesem Browser blockiert. Nur seine Einstellungen können das ändern.", ja: "このブラウザでブロックされています。ブラウザの設定からのみ許可できます。", zh: "已在此浏览器中被拦截。只能在浏览器设置里重新允许。" },
    "push.working": { en: "Working…", ar: "جارٍ…", es: "Trabajando…", fr: "En cours…", de: "Läuft…", ja: "処理中…", zh: "处理中…" },
